#include <atomic>
#include <chrono>
#include <cstdlib>
#include <iostream>
#include <string>
#include <thread>
#include <vector>

#include <gtest/gtest.h>

#include <fastdds/dds/domain/DomainParticipant.hpp>
#include <fastdds/dds/domain/DomainParticipantFactory.hpp>
#include <fastdds/dds/domain/DomainParticipantListener.hpp>
#include <fastdds/rtps/builtin/data/ParticipantBuiltinTopicData.hpp>
#include <fastdds/dds/domain/qos/DomainParticipantQos.hpp>
#include <fastdds/dds/publisher/DataWriter.hpp>
#include <fastdds/dds/publisher/Publisher.hpp>
#include <fastdds/dds/subscriber/DataReader.hpp>
#include <fastdds/dds/subscriber/Subscriber.hpp>
#include <fastdds/dds/topic/Topic.hpp>
#include <fastdds/dds/topic/TypeSupport.hpp>
#include <fastdds/rtps/common/Locator.hpp>
#include <fastdds/utils/IPLocator.hpp>

#include "BlackboxTests.hpp"
#include "../types/HelloWorldPubSubTypes.hpp"

namespace eprosima {
namespace fastdds {
namespace dds {

static unsigned env_or(
        const char* name,
        unsigned def)
{
    const char* value = std::getenv(name);
    return (nullptr != value) ? static_cast<unsigned>(std::atoi(value)) : def;
}

static rtps::Locator_t udp_locator(
        uint32_t port)
{
    rtps::Locator_t locator;
    rtps::IPLocator::setIPv4(locator, 127, 0, 0, 1);
    locator.port = port;
    return locator;
}

static rtps::Locator_t multicast_locator(
        uint32_t port)
{
    rtps::Locator_t locator;
    rtps::IPLocator::setIPv4(locator, 239, 255, 0, 1);
    locator.port = port;
    return locator;
}

class CountingListener : public DomainParticipantListener
{
public:

    void on_participant_discovery(
            DomainParticipant*,
            rtps::ParticipantDiscoveryStatus status,
            const ParticipantBuiltinTopicData&,
            bool&) override
    {
        if (rtps::ParticipantDiscoveryStatus::DISCOVERED_PARTICIPANT == status)
        {
            ++discovered;
        }
    }

    std::atomic<unsigned> discovered{0};
};

/**
 * Reproducer for the ABBA deadlock between a participant's EDP temporary `ProxyPool` and the
 * mutexes of its own builtin SEDP readers.
 *
 * Two opposite lock orders exist over those two resources:
 *
 *  - `EDPBaseSUBListener::add_reader_from_change()` takes a pool slot while the SEDP reader
 *    mutex is already held (the listener runs from `StatefulReader::processDataMsg()` with
 *    that mutex locked) and only releases the mutex afterwards.           [mutex -> pool]
 *  - `EDPSimple::assignRemoteEndpoints()` takes a pool slot and keeps it across
 *    `matched_writer_add_edp()`, which locks that very same reader mutex.  [pool -> mutex]
 *
 * `PDP::temp_reader_proxies_` has 4 slots and `ProxyPool::get()` waits on a condition variable
 * with no timeout, so once the service participant's metatraffic reception threads hold every
 * slot while waiting for the mutex, and one more thread holds the mutex while waiting for a
 * slot, the process is stuck for good.
 *
 * Under `INTRAPROCESS_FULL` (the default) an application thread deterministically ends up on
 * the `[mutex -> pool]` side: creating a DataReader on one participant delivers its DATA(r)
 * synchronously, on the calling thread, into the SEDP reader of another participant of the
 * same process.
 *
 * The service participant is given several metatraffic unicast locators on purpose. Each one
 * is served by its own reception thread, and each noise participant announces itself straight
 * to one of them through `initialPeersList`, so that several threads run
 * `assignRemoteEndpoints()` at the same time. A single metatraffic receiver would process the
 * DATA(p) messages one after another and could never hold more than one slot at a time.
 */
TEST(DDSEdpDeadlock, edp_proxy_pool_vs_sedp_reader_mutex)
{
    const unsigned receivers = env_or("FASTDDS_REPRO_RECEIVERS", 8u);
    const unsigned noise_count = env_or("FASTDDS_REPRO_NOISE", 2u);
    const unsigned run_seconds = env_or("FASTDDS_REPRO_SECONDS", 60u);
    const unsigned stall_seconds = env_or("FASTDDS_REPRO_STALL", 20u);
    const uint32_t domain_id = static_cast<uint32_t>(GET_PID() % 230);
    // Keep the service participant's ports clear of the 7400 + 250 * domain family.
    const uint32_t base_port = 31000u + static_cast<uint32_t>(GET_PID() % 200) * 32u;

    auto factory = DomainParticipantFactory::get_shared_instance();
    LibrarySettings old_library_settings;
    factory->get_library_settings(old_library_settings);
    {
        LibrarySettings library_settings;
        library_settings.intraprocess_delivery = IntraprocessDeliveryType::INTRAPROCESS_FULL;
        factory->set_library_settings(library_settings);
    }

    // A stalled run means the deadlock reproduced. The main thread cannot report it (it is one
    // of the blocked threads), so a watchdog aborts the process: the test fails and every
    // thread's stack stays in place for a debugger.
    std::atomic<uint64_t> progress{0};
    std::atomic<bool> stop_watchdog{false};
    std::thread watchdog([&]()
            {
                uint64_t last_seen = 0;
                auto last_change = std::chrono::steady_clock::now();
                while (!stop_watchdog.load())
                {
                    std::this_thread::sleep_for(std::chrono::milliseconds(200));
                    const uint64_t seen = progress.load();
                    if (seen != last_seen)
                    {
                        last_seen = seen;
                        last_change = std::chrono::steady_clock::now();
                        continue;
                    }
                    if (std::chrono::steady_clock::now() - last_change >
                    std::chrono::seconds(stall_seconds))
                    {
                        std::cerr << "\nDEADLOCK: no progress for " << stall_seconds << "s after "
                                  << last_seen << " DataReader create/delete steps.\n"
                                  << "Expect one thread in ProxyPool::get and several in "
                                  << "StatefulReader::matched_writer_add_edp.\n";
                        std::cerr.flush();
                        std::abort();
                    }
                }
            });

    {
        // Service participant: plays ROS2_SERVICE from the original report. Several metatraffic
        // unicast locators, so it has several metatraffic reception threads.
        DomainParticipantQos service_qos = PARTICIPANT_QOS_DEFAULT;
        for (unsigned i = 0; i < receivers; ++i)
        {
            service_qos.wire_protocol().builtin.metatrafficUnicastLocatorList.push_back(
                udp_locator(base_port + i));
        }
        // Keep the standard multicast metatraffic locator, so the default participant still
        // discovers this one the usual way.
        service_qos.wire_protocol().builtin.metatrafficMulticastLocatorList.push_back(
            multicast_locator(7400u + 250u * domain_id));

        CountingListener service_listener;
        DomainParticipant* service = factory->create_participant(domain_id, service_qos,
                        &service_listener);
        ASSERT_NE(nullptr, service);
        DomainParticipant* def = factory->create_participant(domain_id, PARTICIPANT_QOS_DEFAULT);
        ASSERT_NE(nullptr, def);

        TypeSupport type_support(new HelloWorldPubSubType());
        ASSERT_EQ(RETCODE_OK, type_support.register_type(service, "HelloWorld"));
        ASSERT_EQ(RETCODE_OK, type_support.register_type(def, "HelloWorld"));

        // Endpoints on both sides, so the two participants match over SEDP and the
        // cross-participant intraprocess EDP path is in place.
        Subscriber* service_sub = service->create_subscriber(SUBSCRIBER_QOS_DEFAULT);
        Publisher* service_pub = service->create_publisher(PUBLISHER_QOS_DEFAULT);
        ASSERT_NE(nullptr, service_sub);
        ASSERT_NE(nullptr, service_pub);
        Topic* service_topic = service->create_topic("edp_deadlock", "HelloWorld", TOPIC_QOS_DEFAULT);
        ASSERT_NE(nullptr, service_topic);
        ASSERT_NE(nullptr, service_sub->create_datareader(service_topic, DATAREADER_QOS_DEFAULT));
        ASSERT_NE(nullptr, service_pub->create_datawriter(service_topic, DATAWRITER_QOS_DEFAULT));

        Subscriber* def_sub = def->create_subscriber(SUBSCRIBER_QOS_DEFAULT);
        ASSERT_NE(nullptr, def_sub);
        Topic* def_topic = def->create_topic("edp_deadlock", "HelloWorld", TOPIC_QOS_DEFAULT);
        ASSERT_NE(nullptr, def_topic);

        std::this_thread::sleep_for(std::chrono::seconds(2));
        std::cout << "service discovered " << service_listener.discovered.load()
                  << " participant(s) before the noise starts (expect 1: the default one)\n";

        // Noise participants: each announces itself directly to one of the service
        // participant's metatraffic locators, so a different reception thread of the service
        // participant runs assignRemoteEndpoints() for each of them.
        std::atomic<bool> stop_noise{false};
        std::vector<std::thread> noise_threads;
        for (unsigned r = 0; r < receivers; ++r)
        {
            noise_threads.emplace_back([&, r]()
                    {
                        // One thread per metatraffic locator of the service participant, so
                        // that a different reception thread of that participant runs
                        // assignRemoteEndpoints() for each of them at the same time.
                        DomainParticipantQos noise_qos = PARTICIPANT_QOS_DEFAULT;
                        noise_qos.wire_protocol().builtin.initialPeersList.push_back(
                            udp_locator(base_port + r));

                        while (!stop_noise.load())
                        {
                            std::vector<DomainParticipant*> burst;
                            for (unsigned i = 0; i < noise_count && !stop_noise.load(); ++i)
                            {
                                DomainParticipant* participant =
                                        factory->create_participant(domain_id, noise_qos);
                                if (nullptr != participant)
                                {
                                    burst.push_back(participant);
                                }
                            }
                            for (DomainParticipant* participant : burst)
                            {
                                participant->delete_contained_entities();
                                factory->delete_participant(participant);
                            }
                        }
                    });
        }

        // Main thread: the [mutex -> pool] side of the cycle.
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(run_seconds);
        while (std::chrono::steady_clock::now() < deadline)
        {
            DataReader* reader = def_sub->create_datareader(def_topic, DATAREADER_QOS_DEFAULT);
            ASSERT_NE(nullptr, reader);
            progress.fetch_add(1);
            ASSERT_EQ(RETCODE_OK, def_sub->delete_datareader(reader));
            progress.fetch_add(1);
        }

        stop_noise.store(true);
        for (std::thread& thread : noise_threads)
        {
            thread.join();
        }

        std::cout << "Completed " << (progress.load() / 2) << " create/delete cycles.\n";
        std::cout << "service discovered " << service_listener.discovered.load()
                  << " participant(s) in total\n";

        def->delete_contained_entities();
        service->delete_contained_entities();
        factory->delete_participant(def);
        factory->delete_participant(service);
    }

    stop_watchdog.store(true);
    watchdog.join();

    factory->set_library_settings(old_library_settings);
}

} // namespace dds
} // namespace fastdds
} // namespace eprosima
```

</details>

## Backtrace of the hang

All five threads of the cycle operate on the **same** `StatefulReader` (`0x5555560da970`, the
service participant's SEDP subscriptions reader) and the same `EDPSimple` (`0x5555560d3ce0`).

Thread 1 — the application thread creating a DataReader. It holds the reader mutex and waits
for a pool slot:

```
#5  std::condition_variable::wait<ProxyPool<ReaderProxyData, 4ul>::get()::{lambda()#1}>(...)
#6  eprosima::ProxyPool<ReaderProxyData, 4ul>::get (this=0x5555560c31c8)     ProxyPool.hpp:222
#7  EDPBaseSUBListener::add_reader_from_change (reader=0x5555560da970,
                                      edp=0x5555560d3ce0)          EDPSimpleListeners.cpp:220
#8  EDPSimpleSUBListener::on_new_cache_change_added                EDPSimpleListeners.cpp:333
#9  StatefulReader::NotifyChanges (this=0x5555560da970)               StatefulReader.cpp:1352
#10 StatefulReader::change_received                                   StatefulReader.cpp:1254
#11 StatefulReader::process_data_msg (this=0x5555560da970)             StatefulReader.cpp:692
                                                               ^-- holds mp_mutex since :575
#12 StatefulWriter::intraprocess_delivery                              StatefulWriter.cpp:424
#13 StatefulWriter::deliver_sample_to_intraprocesses                   StatefulWriter.cpp:610
#14 StatefulWriter::deliver_sample_nts                                StatefulWriter.cpp:2225
#15 FlowControllerImpl<FlowControllerSyncPublishMode, ...>::add_new_sample_impl
                                                                 FlowControllerImpl.hpp:1240
                                                               ^-- synchronous, caller thread
#16 StatefulWriter::unsent_change_added_to_history                     StatefulWriter.cpp:396
#17 WriterHistory::add_change_                                          WriterHistory.cpp:226
#19 EDPSimple::process_reader_proxy_data                                  EDPSimple.cpp:555
#20 EDP::new_reader_proxy_data                                                  EDP.cpp:384
#21 BuiltinProtocols::add_reader                                  BuiltinProtocols.cpp:310
#22 RTPSParticipantImpl::register_reader                       RTPSParticipantImpl.cpp:1499
#24 DataReaderImpl::enable                                           DataReaderImpl.cpp:305
#28 SubscriberImpl::create_datareader                               SubscriberImpl.cpp:239
```

Threads 7, 8, 11 and one more — the service participant's four metatraffic reception threads
(`dds.udp.31450`, `dds.udp.31451`, `dds.udp.31454`, …). Each one holds a pool slot taken at
`EDPSimple.cpp:763` and waits on that very same mutex (futex `0x5555560daae8`):

```
#1  __GI___lll_lock_wait (futex=0x5555560daae8)
#6  std::recursive_timed_mutex::lock (this=0x5555560daae8)
#9  StatefulReader::matched_writer_add_edp (this=0x5555560da970)       StatefulReader.cpp:207
#10 EDPSimple::assignRemoteEndpoints (this=0x5555560d3ce0)               EDPSimple.cpp:807
                                      ^-- subscriptions_reader_; pool slot still held from :763
#11 PDPSimple::assignRemoteEndpoints                                     PDPSimple.cpp:584
#13 PDPListener::process_alive_data                                     PDPListener.cpp:221
#24 UDPChannelResource::perform_listen_operation                 UDPChannelResource.cpp:78
```

Exactly 4 threads in `matched_writer_add_edp`, one per pool slot, and exactly 1 in
`ProxyPool::get` — the 4 + 1 shape the cycle predicts.

---

# Fast DDS version/commit

Reproduced on **master `cf92048fd`** ("Keep room in ReaderHistory for missing changes
(#6616)", 2026-11-11), built with `-DCMAKE_BUILD_TYPE=RelWithDebInfo`.

Originally hit in production on **v2.6.10**. By code inspection both edges of the cycle are
also present on 2.14.x (`EDPSimple.cpp:765 -> :807` and
`EDPSimpleListeners.cpp:183 -> :225`), so the supported range looks affected as well; I have
only reproduced it on master.

---

# Platform/Architecture

Reproduced on Ubuntu 24.04 (Noble) x86_64, gcc 13.3.0, 24 cores. With respect to the Tier 1
list in this template that is "Other"; the issue is a lock-order inversion in
platform-independent code, and the original production failure was on a different platform
(an embedded Linux board).

---

# Transport layer

- Default configuration, UDPv4 & SHM
- Intra-process

---

# Additional context

## Original production symptom

A process hosting two participants — a default one and a second one dedicated to ROS 2
services — hung at startup on v2.6.10 while creating a DataReader on the first participant.
The board's profile enforces SHM metatraffic, which gives the second participant enough
metatraffic reception threads to exhaust the 4-slot pool. Setting `intraprocess_delivery` to
`INTRAPROCESS_USER_DATA_ONLY` before creating any participant removes the `M -> S` edge from
the startup path and avoids the hang completely; that is what we deployed. It costs
intra-process delivery for all builtin traffic, and it is not a workaround users can be
expected to discover from a silent hang.

## This looks like an oversight rather than intended behaviour

The "release the pool slot before taking an endpoint mutex" discipline already exists in the
codebase. `assignRemoteEndpoints()` is simply where it was not applied:

* `TypeLookupManager::check_type_identifier_received()` copies the proxy out of the pool with
  the explicit comment **"Make a copy of the proxy to free the EDP pool"**
  (`src/cpp/fastdds/builtin/type_lookup_service/TypeLookupManager.cpp:398` and `:414`).
* `EDP::pairing_reader_proxy_with_any_local_writer()` calls `temp_writer_proxy_data.reset()`
  at `src/cpp/rtps/builtin/discovery/endpoint/EDP.cpp:1325`, immediately before
  `w.matched_reader_add_edp(*rdata)` at `:1336`. The symmetric
  `pairing_writer_proxy_with_any_local_reader()` does the same at `:1521`/`:1532`.
* `PDPListener` documents an explicit lock order — *"Release reader lock to avoid ABBA lock.
  PDP mutex should always be first."*
  (`src/cpp/rtps/builtin/discovery/participant/PDPListener.cpp:90`). The `ProxyPool` was
  never folded into that order.
* `add_reader_from_change()`'s own comment, *"At this point, we can release the reader lock
  because the change is not used"*, shows the intent not to hold the reader mutex across long
  operations — yet an untimed blocking acquisition sits 62 lines above it.

## Secondary finding: a second inversion, between the two pools

Code inspection only; I have **not** observed this one.

In v2.6.10 `add_reader_from_change()` released its pool slot *before* pairing. On master the
`reset()` moved to *after* pairing (`EDPSimpleListeners.cpp:302`, while
`pairing_reader_proxy_with_any_local_writer()` is called at `:266`), and pairing acquires a
slot of the *other* pool. That yields opposite orders:

* `add_writer_from_change()` holds a **writer** slot (`:75`), and
  `pairing_writer_proxy_with_any_local_reader()` takes a **reader** slot ⇒ `W -> R`
* `add_reader_from_change()` holds a **reader** slot (`:220`), and
  `pairing_reader_proxy_with_any_local_writer()` takes a **writer** slot ⇒ `R -> W`

Closing that one needs 4 threads in each listener, so it is far less likely than the primary
cycle, but it is a regression relative to 2.6.x and worth addressing in the same pass.

## Suggested fix

The smallest change that breaks the primary cycle is to stop `assignRemoteEndpoints()` from
holding pool slots across the `matched_*_add_edp()` calls, using function-local proxies
instead of the pool. Sketch — **not yet compiled or tested**, I can validate it against the
reproducer if the direction looks right:

```diff
--- a/src/cpp/rtps/builtin/discovery/endpoint/EDPSimple.cpp
+++ b/src/cpp/rtps/builtin/discovery/endpoint/EDPSimple.cpp
-    auto temp_reader_proxy_data = get_temporary_reader_proxies_pool().get();
+    // Do NOT take a proxy from the EDP pool here: the matched_*_add_edp() calls below
+    // acquire builtin endpoint mutexes, while EDPBaseSUBListener::add_reader_from_change()
+    // acquires the pool with a builtin reader mutex already held. Holding a pool slot
+    // across an endpoint mutex closes an ABBA cycle, and ProxyPool::get() has no timeout.
+    const auto& alloc = mp_PDP->getRTPSParticipant()->get_const_attributes().allocation;
+    ReaderProxyData rpd_storage(alloc.locators.max_unicast_locators,
+                                alloc.locators.max_multicast_locators,
+                                alloc.data_limits, alloc.content_filter);
+    ReaderProxyData* temp_reader_proxy_data = &rpd_storage;
```

…and the equivalent for `temp_writer_proxy_data`. The rest of the function body is unchanged,
since `->` still applies. `assignRemoteEndpoints()` runs once per discovered remote
participant and already performs up to eight `matched_*_add_edp()` calls, so two extra
allocations there should not be measurable. `EDPServer.cpp:229`/`:285` contain the same
pattern and would need the same treatment.

This touches only `.cpp` files, so it is ABI- and API-compatible and backportable to the
supported branches as-is. For contrast, adding a timeout overload to `ProxyPool::get()` would
be a cleaner systemic fix on master, where `ProxyPool.hpp` is internal — but on 2.6.x that
header is installed publicly (`include/fastrtps/utils/ProxyPool.hpp`), so that variant is not
backportable there.

Happy to open a PR if the approach looks right to you.

## Severity

We would argue this qualifies as critical for backport purposes:

* it occurs with **default** library settings, no special QoS and no special transport
  configuration;
* the triggering layout — two participants in one process — is standard for ROS 2
  applications;
* it is a permanent hang during startup rather than a transient slowdown: both waits are
  untimed, so the process can neither recover nor report anything;
* the application can neither detect nor avoid it.
